import * as ko from 'knockout';
import * as $ from 'jquery';
import { addDisposeCallback } from '../serializer/_internal';
import { getTemplate } from '../property-grid/widgets/templateUtils';
import { getParentContainer } from './_utils';
ko.bindingHandlers['focus'] = {
    init: function (element, valueAccessor) {
        const visible = valueAccessor().on || valueAccessor();
        const subscription = visible.subscribe((newVal) => {
            if (newVal) {
                setTimeout(() => {
                    $.fn.constructor(element).find(':input').focus();
                }, 1);
            }
        });
        addDisposeCallback(element, function () {
            subscription.dispose();
        });
    }
};
ko.bindingHandlers['svgAttrs'] = {
    update: function (element, valueAccessor, allBindingsAccessor, viewModel) {
        element.setAttribute('xmlns', 'http://www.w3.org/2000/svg');
        element.setAttribute('xmlns:xlink', 'http://www.w3.org/1999/xlink');
    }
};
ko.bindingHandlers['dxEditorPopupTemplate'] = {
    init: function (element, valueAccessor) {
        const values = valueAccessor();
        const popupTemplateName = getTemplate(values.templateName);
        if (popupTemplateName) {
            const wrapper = document.createElement('div');
            wrapper.innerHTML = popupTemplateName;
            const container = getParentContainer(element);
            container.append(wrapper);
            ko.applyBindings(values.data, wrapper);
            addDisposeCallback(element, function () {
                setTimeout(() => wrapper.remove(), 1);
            });
        }
    }
};
